args.command:
TD=$(mktemp -d); echo "$TD"; mkdir -p "$TD/passpkg" "$TD/failpkg" "$TD/builderr"; cat > "$TD/go.mod" <<'EOF'
module example.com/probe

go 1.21
EOF
cat > "$TD/passpkg/pass.go" <<'EOF'
package passpkg

func Add(a, b int) int { return a + b }
EOF
cat > "$TD/passpkg/pass_test.go" <<'EOF'
package passpkg

import "testing"

func TestAdd(t *testing.T) {
	if Add(1, 2) != 3 {
		t.Errorf("bad add")
	}
}

func TestSkip(t *testing.T) {
	t.Skip("skipping")
}
EOF
cat > "$TD/failpkg/fail.go" <<'EOF'
package failpkg

func Sub(a, b int) int { return a - b }
EOF
cat > "$TD/failpkg/fail_test.go" <<'EOF'
package failpkg

import "testing"

func TestSub(t *testing.T) {
	if Sub(1, 2) != -1 {
		t.Errorf("bad sub")
	}
}

func TestFail(t *testing.T) {
	t.Errorf("intentional failure")
}
EOF
cat > "$TD/builderr/broken.go" <<'EOF'
package builderr

func Broken( { return 1 }
EOF
ls -R "$TD"

TD=$(mktemp -d); echo "$TD" > /tmp/probe_td_path; mkdir -p "$TD/passpkg" "$TD/failpkg" "$TD/builderr"
cat > "$TD/go.mod" <<'EOF'
module example.com/probe

go 1.21
EOF
cat > "$TD/passpkg/pass.go" <<'EOF'
package passpkg

func Add(a, b int) int { return a + b }
EOF
cat > "$TD/passpkg/pass_test.go" <<'EOF'
package passpkg

import "testing"

func TestAdd(t *testing.T) {
	if Add(1, 2) != 3 {
		t.Errorf("bad add")
	}
}

func TestSkip(t *testing.T) {
	t.Skip("skipping")
}
EOF
cat > "$TD/failpkg/fail.go" <<'EOF'
package failpkg

func Sub(a, b int) int { return a - b }
EOF
cat > "$TD/failpkg/fail_test.go" <<'EOF'
package failpkg

import "testing"

func TestSub(t *testing.T) {
	if Sub(1, 2) != -1 {
		t.Errorf("bad sub")
	}
}

func TestFail(t *testing.T) {
	t.Errorf("intentional failure")
}
EOF
cat > "$TD/builderr/broken.go" <<'EOF'
package builderr

func Broken( { return 1 }
EOF
TD=$(cat /tmp/probe_td_path); cd "$TD" && export GOPROXY=off GOFLAGS=-mod=mod
for i in 1 2 3; do /workspace/executable test -count=1 ./passpkg/ 2>/dev/null | od -c | tail -2; echo "exit=${PIPESTATUS[0]}"; done
for i in 1 2 3; do /workspace/executable test -count=1 ./failpkg/ 2>/dev/null | od -c | tail -2; echo "exit=${PIPESTATUS[0]}"; done
